using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The MCP SDK instantiates this class per-request via DI,
/// so constructor-injected services (HttpClient, loggers, etc.) just work.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // The DI container injects an HttpClient configured in Program.cs.
    public WeatherTools(HttpClient httpClient)
    {
        _http = httpClient;
    }

    [McpServerTool("get_weather")]
    [Description("Get current weather for a location (temperature, wind speed, conditions).")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast" +
                  $"?latitude={latitude}&longitude={longitude}" +
                  $"&current_weather=true";

        var response = await _http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync());

        var weather = doc.RootElement.GetProperty("current_weather");

        return $"Temperature: {weather.GetProperty("temperature")}°C, " +
               $"Wind: {weather.GetProperty("windspeed")} km/h, " +
               $"Code: {weather.GetProperty("weathercode")}";
    }

    [McpServerTool("get_temperature")]
    [Description("Get only the current temperature in Celsius for a location.")]
    public async Task<string> GetTemperatureAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast" +
                  $"?latitude={latitude}&longitude={longitude}" +
                  $"&current_weather=true";

        var response = await _http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync());

        var temp = doc.RootElement
            .GetProperty("current_weather")
            .GetProperty("temperature");

        return $"{temp}°C";
    }
}

