using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    // Register HttpClient so it can be injected into tool classes.
    .AddSingleton<HttpClient>()
    // Wire up the MCP server with stdio transport and discover tools
    // from the current assembly (any class marked [McpServerToolType]).
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

